<?php require "vendor/autoload.php"; $app = require_once "bootstrap/app.php"; $app->make("Illuminate\Contracts\Console\Kernel")->bootstrap(); $s = App\Models\Shop::where("slug", "goodwill")->first(); if(!$s) { echo "No shop"; exit; } echo json_encode(["id" => $s->id, "products" => App\Models\Product::where("shop_id", $s->id)->count(), "categories" => App\Models\Category::where("shop_id", $s->id)->count(), "sold_out" => App\Models\Product::where("shop_id", $s->id)->where("is_sold_out", true)->count()]);
